import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.tsx';
import './styles/index.css';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

import React, { useState, useEffect } from 'react';
import './styles/index.css';
import { Activity, Category, DateState } from './types';
import Dashboard from './components/Dashboard';
import ActivityList from './components/ActivityList';
import Header from './components/Header';

const App: React.FC = () => {
  const [activities, setActivities] = useState<Activity[]>([]);
  const [dateState, setDateState] = useState<DateState>({
    currentDate: new Date().toISOString().split('T')[0],
    selectedDate: new Date().toISOString().split('T')[0],
  });
  const [darkMode, setDarkMode] = useState<boolean>(true);
  const [categoryFilter, setCategoryFilter] = useState<string>('all');
  const [newActivityName, setNewActivityName] = useState<string>('');

  // Load data from localStorage on app start
  useEffect(() => {
    const savedData = localStorage.getItem('pulseboard-data');
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        setActivities(parsed.activities || []);
        setDateState({
          currentDate: new Date().toISOString().split('T')[0],
          selectedDate: new Date().toISOString().split('T[0],
        });
      } catch (error) {
        console.error('Failed to parse saved data:', error);
        setActivities([]);
      }
    }
  }, []);

  // Save data to localStorage whenever activities change
  useEffect(() => {
    const dataToSave = {
      version: '1.0',
      activities,
      dateState,
    };
    localStorage.setItem('pulseboard-data', JSON.stringify(dataToSave));
  }, [activities, dateState]);

  const addActivity = (name: string, description?: string, category?: string) => {
    const newActivity: Activity = {
      id: Date.now().toString(),
      name,
      description,
      category,
    };
    setActivities([...activities, newActivity]);
  };

  const updateActivity = (id: string, updates: Partial<Activity>) => {
    setActivities(activities.map(activity => 
      activity.id === id ? { ...activity, ...updates } : activity
    ));
  };

  const deleteActivity = (id: string) => {
    setActivities(activities.filter(activity => activity.id !== id));
  };

  const toggleActivity = (activityId: string, date: string) => {
    // In a real app, we would store activity status per date
    // For now, we'll just toggle the checkbox in the UI
    setActivities(activities.map(activity => 
      activity.id === activityId ? { ...activity, completed: !activity.completed } : activity
    ));
  };

  const handleAddActivity = () => {
    if (newActivityName.trim()) {
      addActivity(newName);
      setNewActivityName('');
    }
  };

  const handleDateChange = (newDate: string) => {
    setDateState({ ...dateState, selectedDate: newDate });
  };

  const handlePreviousDay = () => {
    const currentDate = new Date(dateState.selectedDate);
    currentDate.setDate(currentDate.getDate() - 1);
    handleDateChange(currentDate.toISOString().split('T')[0]);
  };

  const handleNextDay = () => {
    const currentDate = new Date(dateState.selectedDate);
    currentDate.setDate(currentDate.getDate() + 1);
    handleDateChange(currentDate.toISOString().split('T')[0]);
  };

  const handleToday = () => {
    handleDateChange(new Date().toISOString().split('T')[0]);
  };

  const filteredActivities = categoryFilter === 'all'
    ? activities
    : activities.filter(activity => activity.category === categoryFilter);

  return (
    <div className={`app ${darkMode ? 'dark' : 'light'}`
      data-theme={darkMode ? 'dark' : 'light'}
    >
      <div className="app-container">
        <Header 
          darkMode={darkMode}
          onToggleDarkMode={() => setDarkMode(!darkMode)}
          onAddActivity={handleAddActivity}
          newActivityName={newActivityName}
          setNewActivityName={setNewActivityName}
        />
        <Dashboard 
          activities={filteredActivities}
          currentDate={dateState.selectedDate}
          darkMode={darkMode}
        />
        <ActivityList 
          activities={filteredActivities}
          onToggleActivity={toggleActivity}
          onUpdateActivity={updateActivity}
          onDeleteActivity={deleteActivity}
        />
      </div>
    </div>
  );
};

export default App;

