import React, { useState, useEffect } from 'react';
import './styles/index.css';
import { Activity, Category, DateState } from './types';
import Dashboard from './components/Dashboard';
import ActivityList from './components/ActivityList';
import Header from './components/Header';

const App: React.FC = () => {
  const [activities, setActivities] = useState<Activity[]>([]);
  const [dateState, setDateState] = useState<DateState>({
    currentDate: new Date().toISOString().split('T')[0],
    selectedDate: new Date().toISOString().split('T')[0],
  });
  const [darkMode, setDarkMode] = useState<boolean>(true);
  const [categoryFilter, setCategoryFilter] = useState<string>('all');
  const [newActivityName, setNewActivityName] = useState<string>('');

  // Load data from localStorage on app start
  useEffect(() => {
    const savedData = localStorage.getItem('pulseboard-data');
    if (savedData) {
      try {
        const parsed = JSON.parse(savedData);
        setActivities(parsed.activities || []);
        setDateState({
          currentDate: new Date().toISOString().split('T')[0],
          selectedDate: new Date().toISOString().split('T')[0],
        });
      } catch (error) {
        console.error('Failed to parse saved data:', error);
        setActivities([]);
      }
    }
  }, []);

  // Save data to localStorage whenever activities change
  useEffect(() => {
    const dataToSave = {
      version: '1.0',
      activities,
      dateState,
    };
    localStorage.setItem('pulseboard-data', JSON.stringify(dataToSave));
  }, [activities, dateState]);

  const addActivity = (name: string, description?: string, category?: string) => {
    const newActivity: Activity = {
      id: Date.now().toString(),
      name,
      description,
      category,
    };
    setActivities([...activities, newActivity]);
  };

  const updateActivity = (id: string, updates: Partial<Activity>) => {
    setActivities(activities.map(activity => 
      activity.id === id ? { ...activity, ...updates } : activity
    ));
  };

  const deleteActivity = (id: string) => {
    setActivities(activities.filter(activity => activity.id !== id));
  };

  const toggleActivity = (activityId: string, date: string) => {
    // In a real app, we would store activity status per date
    // For now, we'll just toggle the checkbox in the UI
    setActivities(activities.map(activity => 
      activity.id === activityId ? { ...activity, completed: !activity.completed } : activity
    ));
  };

  const handleAddActivity = () => {
    if (newActivityName.trim()) {
      addActivity(newActivityName);
      setNewActivityName('');
    }
  };

  const handleDateChange = (newDate: string) => {
    setDateState({ ...dateState, selectedDate: newDate });
  };

  const handlePreviousDay = () => {
    const currentDate = new Date(dateState.selectedDate);
    currentDate.setDate(currentDate.getDate() - 1);
    handleDateChange(currentDate.toISOString().split('T')[0]);
  };

  const handleNextDay = () => {
    const currentDate = new Date(dateState.selectedDate);
    currentDate.setDate(currentDate.getDate() + 1);
    handleDateChange(currentDate.toISOString().split('T')[0]);
  };

  const handleToday = () => {
    handleDateChange(new Date().toISOString().split('T')[0]);
  };

  const filteredActivities = categoryFilter === 'all'
    ? activities
    : activities.filter(activity => activity.category === categoryFilter);

  return (
    <div className={`app ${darkMode ? 'dark' : 'light'}`
      data-theme={darkMode ? 'dark' : 'light'}
    >
      <div className="app-container">
        <Header 
          darkMode={darkMode}
          onToggleDarkMode={() => setDarkMode(!darkMode)}
          onAddActivity={handleAddActivity}
          newActivityName={newActivityName}
          setNewActivityName={setNewActivityName}
        />
        <Dashboard 
          activities={filteredActivities}
          currentDate={dateState.selectedDate}
          darkMode={darkMode}
        />
        <ActivityList 
          activities={filteredActivities}
          onToggleActivity={toggleActivity}
          onUpdateActivity={updateActivity}
          onDeleteActivity={deleteActivity}
        />
      </div>
    </div>
  );
};

export default App;

export interface Activity {
  id: string;
  name: string;
  description?: string;
  category?: string;
  completed?: boolean;
}

export interface DateState {
  currentDate: string;
  selectedDate: string;
}

import React, { useState } from 'react';

interface HeaderProps {
  darkMode: boolean;
  onToggleDarkMode: () => void;
  newActivityName: string;
  setNewActivityName: (name: string) => void;
  onAddActivity: () => void;
}

const Header: React.FC<HeaderProps> = ({ darkMode, onToggleDarkMode, newActivityName, setNewActivityName, onAddActivity }) => {
  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      onAddActivity();
    }
  };

  return (
    <header className="header">
      <div className="header-content">
        <h1 className="app-title">PulseBoard</h1>
        <div className="header-actions">
          <button 
            className="toggle-dark-mode"
            onClick={onToggleDarkMode}
            aria-label={darkMode ? "Switch to light mode" : "Switch to dark mode"}
  >
            {darkMode ? '🌙' : '☀️'}
          </button>
        </div>
      </div>

      <div className="add-activity">
        <input
          type="text"
          value={newActivityName}
          onChange={(e) => setNewActivityName(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder="Add new activity"
          className="activity-input"
        />
        <button 
          onClick={onAddActivity}
          className="add-button"
          aria-label="Add activity"
        >
          + Add
        </button>
      </div>
    </header>
  );
};

export default Header;

import React from 'react';
import { Activity } from '../types';

interface DashboardProps {
  activities: Activity[];
  currentDate: string;
  darkMode: boolean;
}

const Dashboard: React.FC<DashboardProps> = ({ activities, currentDate, darkMode }) => {
  const completedActivities = activities.filter(activity => activity.completed).length;
  const totalActivities = activities.length;
  const progress = totalActivities > 0 ? Math.round((completedActivities / totalActivities) * 100) : 0;

  const getActivitiesByCategory = () => {
    const categories: Record<string, number> = {};
    activities.forEach(activity => {
      const category = activity.category || 'uncategorized';
      if (categories[category]) {
        categories[category]++;
      } else {
        categories[category] = 1;
      }
    });
    return categories;
  };

  const categoryStats = getActivitiesByCategory();

  return (
    <div className={`dashboard ${darkMode ? 'dark' : 'light'}">
      <div className="dashboard-content">
        <div className="progress-container">
          <h2>Today's Progress</h2>
          <div className="progress-info">
            <span className="completed-count">{completedActivities}/{totalActivities}</span>
            <span className="progress-percentage">{progress}%</span>
          </div>
          <div className="progress-bar">
            <div 
              className="progress-fill" 
              style={{ width: `${progress}%` }}
            ></div>
          </div>
        </div>

        <div className="category-stats">
          <h3>By Category</h3>
          {Object.entries(categoryStats).map(([category, count]) => (
            <div key={category} className="category-stat">
              <span className="category-name">{category}</span>
              <span className="category-count">{count}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import ActivityItem from './ActivityItem';

interface ActivityListProps {
  activities: any[];
  onToggleActivity: (id: string, date: string) => void;
  onUpdateActivity: (id: string, updates: any) => void;
  onDeleteActivity: (id: string) => void;
}

const ActivityList: React.FC<ActivityListProps> = ({ 
  activities, 
  onToggleActivity,
  onUpdateActivity,
  onDeleteActivity 
}) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editedName, setEditedName] = useState<string>('');

  const handleEdit = (activity: any) => {
    setEditingId(activity.id);
    setEditedName(activity.name);
  };

  const handleSave = (id: string) => {
    if (editedName.trim()) {
      onUpdateActivity(id, { name: editedName });
      setEditingId(null);
    }
  };

  const handleCancel = () => {
    setEditingId(null);
  };

  const handleDelete = (id: string) => {
    onDeleteActivity(id);
  };

  return (
    <div className="activity-list">
      {activities.length === 0 ? (
        <div className="empty-state">
          <p>No activities added yet. Add some activities to get started!</p>
        </div>
      ) : (
        <ul className="activity-list">
          {activities.map(activity => (
            <li key={activity.id} className="activity-item">
              <ActivityItem 
                activity={activity}
                onEdit={handleEdit}
                onDelete={handleDelete}
                onSave={handleSave}
                onCancel={handleCancel}
                editingId={editingId}
                editedName={editedName}
                setEditedName={setEditedName}
              />
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default ActivityList;

import React, { useState } from 'react';

interface ActivityItemProps {
  activity: any;
  onEdit: (activity: any) => void;
  onDelete: (id: string) => void;
  onSave: (id: string) => void;
  onCancel: () => void;
  editingId: string | null;
  editedName: string;
  setEditedName: (name: string) => void;
}

const ActivityItem: React.FC<ActivityItemProps> = ({ 
  activity,
  onEdit,
  onDelete,
  onSave,
  onCancel,
  editingId,
  editedName,
  setEditedName
}) => {
  const [isHovered, setIsHovered] = useState(false);

  const handleSave = () => {
    onSave(activity.id);
  };

  const handleCancel = () => {
    onCancel();
  };

  const handleEdit = () => {
    onEdit(activity);
  };

  const handleDelete = () => {
    onDelete(activity.id);
  };

  const handleToggle = () => {
    // This would be where we toggle the activity status
  };

  return (
    <div className="activity-item-content">
      <div className="activity-checkbox">
        <input 
          type="checkbox" 
          checked={activity.completed || false}
          onChange={handleToggle}
          className="checkbox"
        />
      </div>
      <div className="activity-content">
        {editingId === activity.id ? (
          <input
            type="text"
            value={editedName}
            onChange={(e) => setEditedName(e.target.value)}
            className="edit-input"
            autoFocus
          />
        ) : (
          <div className="activity-text">
            <span className={activity.completed ? "completed" : ""}>
              {activity.name}
            </span>
          </div>
        )}
        {activity.description && (
          <div className="activity-description">
            {activity.description}
          </div>
        )}
      </div>
      <div className="activity-actions">
        {editingId === activity.id ? (
          <>
            <button 
              onClick={handleSave}
              className="save-button"
              aria-label="Save changes"
            >
              Save
            </button>
            <button 
              onClick={handleCancel}
              className="cancel-button"
              aria-label="Cancel editing"
            >
              Cancel
            </button>
          </>
        ) : (
          <>
            <button 
              onClick={handleEdit}
              className="edit-button"
              aria-label="Edit activity"
            >
              Edit
            </button>
            <button 
              onClick={handleDelete}
              className="delete-button"
              aria-label="Delete activity"
            >
              Delete
            </button>
          </>
        )}
      </div>
