  );
};

export default ActivityItem;

:root {
  --background-color: #ffffff;
  --text-color: #333333;
  --border-color: #e0e0e0;
  --primary-color: #4a90e2;
  --success-color: #4caf50;
  --danger-color: #f44336;
  --warning-color: #ff9800;
  --success-light: #e8f5e9;
  --warning-light: #fff3e0;
  --danger-light: #ffebee;
  --light-gray: #f5f5f5;
  --dark-gray: #f0f0f0;
}

@media (prefers-color-scheme: dark) {
  :root {
    --background-color: #1a1a1a;
    --text-color: #ffffff;
    --border-color: #333333;
    --light-gray: #2d2d2d;
    --dark-gray: #404040;
  }
}

.app {
  min-height: 100vh;
  background-color: var(--background-color);
  color: var(--text-color);
}

.app.dark {
  background-color: #121212;
}

.app-container {
  max-width: 800px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.header {
  margin-bottom: 2rem;
}

.header-content {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1rem;
}

.app-title {
  font-size: 2rem;
  font-weight: bold;
  margin: 0;
}

.header-actions {
  display: flex;
  gap: 1rem;
}

.toggle-dark-mode {
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  padding: 0;
}

.add-activity {
  display: flex;
  gap: 1rem;
  align-items: center;
}

.activity-input {
  flex: 1;
  padding: 0.5rem;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  background: var(--background-color);
  color: var(--text-color);
}

.add-button {
  padding: 0.5rem 1rem;
  background: var(--primary-color);
  color: white;
  border: none;
  border-radius: 4px;
  cursor: pointer;
}

.dashboard {
  background: var(--light-gray);
  padding: 1rem;
  margin-bottom: 1rem;
  border-radius: 8px;
}

.dashboard-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.progress-container {
  flex: 1;
}

.progress-info {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.5rem;
}

.completed-count {
  font-weight: bold;
}

.progress-bar {
  height: 1rem;
  background: var(--border-color);
  border-radius: 0.5rem;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: var(--success-color);
  transition: width 0.3s ease;
}

.category-stats {
  flex: 1;
}

.category-stat {
  display: flex;
  justify-content: space-between;
  padding: 0.5rem 0;
  border-bottom: 1px solid var(--border-color);
}

.category-name {
  font-weight: bold;
}

.category-count {
  color: var(--text-color);
}

.activity-list {
  list-style: none;
  padding: 0;
}

.activity-item {
  margin-bottom: 1rem;
}

.activity-item-content {
  display: flex;
  align-items: center;
  padding: 0.5rem;
  background: var(--background-color);
  border: 1px solid var(--border-color);
  border-radius: 4px;
}

.activity-checkbox {
  padding-right: 0.5rem;
}

.checkbox {
  size: 1rem;
}

.activity-content {
  flex: 1;
}

.activity-text {
  font-weight: bold;
}

.completed {
  text-decoration: line-through;
  color: gray;
}

.activity-description {
  font-size: 0.9rem;
  color: gray;
}

.activity-actions {
  display: flex;
  gap: 0.5rem;
}

.edit-button, .delete-button {
  padding: 0.2rem 0.5rem;
  background: none;
  border: none;
  cursor: pointer;
}

.edit-button {
  color: var(--primary-color);
}

.delete-button {
  color: var(--danger-color);
}

.empty-state {
  text-align: center;
  padding: 2rem;
  color: gray;
}

@media (max-width: 600px) {
  .app-container {
    padding: 1rem;
  }

  .dashboard-content {
    grid-template-columns: 1fr;
  }
}

